// logo_asset.js - the HolmStone logo, pre-baked as a raw RGB bitmap for pdf.js's hand-rolled
// PDF writer to embed with zero image-decoding logic and zero external dependencies.
//
// How this was produced (regenerate if the logo changes): take the source PNG (which has a
// transparent background), crop to its opaque content bounding box, composite it onto a solid
// white background (since it's always placed on the billing slip's white page - no alpha/soft
// mask support needed in the PDF), resize to {width}x{height}, take the raw 8-bit RGB bytes
// (no header), zlib-deflate them, and base64-encode the compressed bytes. pdf.js base64-decodes
// this back into the raw deflate stream and drops it straight into a PDF Image XObject
// (/Filter [/ASCIIHexDecode /FlateDecode]) - no re-compression needed at request time.
module.exports = {
  width: 480,
  height: 400,
  deflatedRgbBase64: "",
};
